package main

import (
	"crypto/aes"
	"crypto/cipher"
	"crypto/rand"
	"errors"
	"io"
	"log"
)

// 方案 1: 使用 AES-GCM 加密（推荐）
func EncryptAESGCM(plaintext, key []byte) ([]byte, error) {
	// 1. 创建 AES cipher
	block, err := aes.NewCipher(key)
	if err != nil {
		return nil, err
	}

	// 2. 创建 GCM 模式
	gcm, err := cipher.NewGCM(block)
	if err != nil {
		return nil, err
	}

	// 3. 生成随机 nonce
	nonce := make([]byte, gcm.NonceSize())
	if _, err := io.ReadFull(rand.Reader, nonce); err != nil {
		return nil, err
	}

	// 4. 加密并认证
	// Seal 自动加密数据并附加认证标签
	ciphertext := gcm.Seal(nonce, nonce, plaintext, nil)
	
	return ciphertext, nil
}

// 使用 AES-GCM 解密
func DecryptAESGCM(ciphertext, key []byte) ([]byte, error) {
	block, err := aes.NewCipher(key)
	if err != nil {
		return nil, err
	}

	gcm, err := cipher.NewGCM(block)
	if err != nil {
		return nil, err
	}

	nonceSize := gcm.NonceSize()
	if len(ciphertext) < nonceSize {
		return nil, errors.New("ciphertext too short")
	}

	nonce := ciphertext[:nonceSize]
	ciphertext = ciphertext[nonceSize:]

	// Open 自动验证认证标签
	// 如果密文被篡改，会返回错误
	plaintext, err := gcm.Open(nil, nonce, ciphertext, nil)
	if err != nil {
		return nil, err // 认证失败！
	}

	return plaintext, nil
}

// 方案 2: 使用 AES-GCM 并支持附加认证数据
func EncryptAESGCMWithAAD(plaintext, key, additionalData []byte) ([]byte, error) {
	block, err := aes.NewCipher(key)
	if err != nil {
		return nil, err
	}

	gcm, err := cipher.NewGCM(block)
	if err != nil {
		return nil, err
	}

	nonce := make([]byte, gcm.NonceSize())
	if _, err := io.ReadFull(rand.Reader, nonce); err != nil {
		return nil, err
	}

	// 附加认证数据（AAD）不会被加密，但会被认证
	ciphertext := gcm.Seal(nonce, nonce, plaintext, additionalData)
	
	return ciphertext, nil
}

func DecryptAESGCMWithAAD(ciphertext, key, additionalData []byte) ([]byte, error) {
	block, err := aes.NewCipher(key)
	if err != nil {
		return nil, err
	}

	gcm, err := cipher.NewGCM(block)
	if err != nil {
		return nil, err
	}

	nonceSize := gcm.NonceSize()
	if len(ciphertext) < nonceSize {
		return nil, errors.New("ciphertext too short")
	}

	nonce := ciphertext[:nonceSize]
	ciphertext = ciphertext[nonceSize:]

	// AAD 必须匹配，否则认证失败
	plaintext, err := gcm.Open(nil, nonce, ciphertext, additionalData)
	if err != nil {
		return nil, err
	}

	return plaintext, nil
}

// 安全地加密敏感数据
func EncryptPassword(password string, key []byte) ([]byte, error) {
	// 安全：使用 GCM 加密密码
	return EncryptAESGCM([]byte(password), key)
}

func EncryptAPIKey(apiKey string, key []byte) ([]byte, error) {
	// 安全：使用 GCM 加密 API 密钥
	// 可以添加 AAD 来绑定上下文信息
	aad := []byte("api-key-v1")
	return EncryptAESGCMWithAAD([]byte(apiKey), key, aad)
}

func main() {
	// 生成安全的密钥
	key := make([]byte, 32) // AES-256
	if _, err := io.ReadFull(rand.Reader, key); err != nil {
		log.Fatal(err)
	}
	
	// 加密
	plaintext := []byte("sensitive data")
	encrypted, err := EncryptAESGCM(plaintext, key)
	if err != nil {
		log.Fatal(err)
	}
	
	// 解密
	decrypted, err := DecryptAESGCM(encrypted, key)
	if err != nil {
		log.Println("Authentication failed! Data may have been tampered with.")
		return
	}
	
	log.Printf("Decrypted: %s\n", decrypted)
}
